using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Shapes;
namespace MooView;

public sealed class ImagePane : Grid
{
    readonly ScrollViewer scroll = new() { HorizontalScrollBarVisibility = ScrollBarVisibility.Hidden, VerticalScrollBarVisibility = ScrollBarVisibility.Hidden, CanContentScroll = false };
    readonly Image image = new() { Stretch = Stretch.Fill, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
    readonly Grid imageHost = new(); readonly Border mapBorder; readonly Canvas map = new() { Width = 164, Height = 112 }; readonly Image mini = new() { Stretch = Stretch.Uniform }; readonly Rectangle viewport = new() { Stroke = Brushes.White, StrokeThickness = 1.5, Fill = new SolidColorBrush(Color.FromArgb(40, 180, 255, 210)), IsHitTestVisible = false };
    GifPlayback? animation; public bool IsAnimated => animation != null; public int AnimationFrame => animation?.FrameIndex ?? 0; public BitmapSource? CurrentBitmap => bitmap; public void StopAnimation() { animation?.Dispose(); animation=null; } public void SetAnimation(GifData data) { SetImage(new WriteableBitmap(data.Width,data.Height,96,96,PixelFormats.Bgra32,null)); animation=new GifPlayback(data); bitmap=animation.Bitmap;image.Source=bitmap;mini.Source=bitmap;Resize();animation.Start(); } public void SetAnimationRunning(bool running) { if(running)animation?.Start();else animation?.Pause(); } BitmapSource? bitmap; int fit; double zoom = 100; Point? drag; double ox, oy; bool panGesture; public string? FilePath { get; set; } public event Action<string>? ExportRequested; public event Action<int>? Navigate; public event Action<double>? ZoomRequested; public event Action? Activated;
    public ImagePane() { Unloaded += (_,_)=>StopAnimation(); Margin = new Thickness(5); ClipToBounds = true; imageHost.Children.Add(image); scroll.Content = imageHost; Children.Add(scroll); map.Children.Add(mini); map.Children.Add(viewport); mapBorder = new Border { Background = new SolidColorBrush(Color.FromArgb(220, 30, 37, 32)), BorderBrush = Brushes.Gray, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(8), Padding = new Thickness(6), Child = map, HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Bottom, Margin = new Thickness(14), Visibility = Visibility.Collapsed }; Children.Add(mapBorder); SizeChanged += (_, _) => Resize(); scroll.ScrollChanged += (_, _) => UpdateMap(); PreviewMouseWheel += Wheel; scroll.PreviewMouseLeftButtonDown += BeginDrag; scroll.MouseMove += ContinueDrag; scroll.MouseLeftButtonUp += (_, _) => EndDrag(); scroll.LostMouseCapture += (_,_) => drag=null; map.MouseLeftButtonDown += (_, e) => { map.CaptureMouse(); MapPan(e); }; map.MouseMove += (_, e) => { if (e.LeftButton == MouseButtonState.Pressed) MapPan(e); }; map.MouseLeftButtonUp += (_, _) => map.ReleaseMouseCapture(); }
    void BeginDrag(object s, MouseButtonEventArgs e) { Activated?.Invoke(); drag=e.GetPosition(this); ox=scroll.HorizontalOffset; oy=scroll.VerticalOffset; panGesture=!Keyboard.Modifiers.HasFlag(ModifierKeys.Control) && (image.Width>ActualWidth+2 || image.Height>ActualHeight+2); scroll.CaptureMouse(); e.Handled=true; }
    void ContinueDrag(object s, MouseEventArgs e) { if(drag is not Point start || e.LeftButton!=MouseButtonState.Pressed)return; var p=e.GetPosition(this); if(panGesture){scroll.ScrollToHorizontalOffset(ox+start.X-p.X);scroll.ScrollToVerticalOffset(oy+start.Y-p.Y);return;} if(Math.Abs(p.X-start.X)<SystemParameters.MinimumHorizontalDragDistance && Math.Abs(p.Y-start.Y)<SystemParameters.MinimumVerticalDragDistance)return; EndDrag(); if(FilePath is string path)ExportRequested?.Invoke(path); }
    void EndDrag() { drag=null; if(Mouse.Captured==scroll)scroll.ReleaseMouseCapture(); }
    public void SetImage(BitmapSource b) { StopAnimation(); bitmap = b; image.Source = b; mini.Source = b; scroll.ScrollToHorizontalOffset(0); scroll.ScrollToVerticalOffset(0); Resize(); }
    public void SetZoom(int mode, double percent) { fit = mode; zoom = percent; Resize(); }
    public void ResetPan() { scroll.ScrollToHorizontalOffset(0); scroll.ScrollToVerticalOffset(0); }
    void Resize() { if (bitmap == null || ActualWidth < 1 || ActualHeight < 1) return; double w = ActualWidth, h = ActualHeight; double s = fit switch { 0 => Math.Min(w / bitmap.PixelWidth, h / bitmap.PixelHeight), 1 => Math.Max(w / bitmap.PixelWidth, h / bitmap.PixelHeight), 2 => w / bitmap.PixelWidth, 3 => 1, _ => zoom / 100 }; image.Width = bitmap.PixelWidth * s; image.Height = bitmap.PixelHeight * s; imageHost.MinWidth = w; imageHost.MinHeight = h; UpdateMap(); }
    void Wheel(object s, MouseWheelEventArgs e) { Activated?.Invoke(); if (Keyboard.Modifiers.HasFlag(ModifierKeys.Control)) { double current = bitmap == null ? 100 : image.Width / bitmap.PixelWidth * 100; ZoomRequested?.Invoke(Math.Clamp(current * (e.Delta > 0 ? 1.15 : 1 / 1.15), 1, 3200)); } else Navigate?.Invoke(e.Delta < 0 ? 1 : -1); e.Handled = true; }
    void UpdateMap() { if (bitmap == null) return; bool needed = image.Width > ActualWidth + 2 || image.Height > ActualHeight + 2; mapBorder.Visibility = needed ? Visibility.Visible : Visibility.Collapsed; if (!needed) return; double scale = Math.Min(164.0 / bitmap.PixelWidth, 112.0 / bitmap.PixelHeight); double mw = bitmap.PixelWidth * scale, mh = bitmap.PixelHeight * scale; mini.Width = mw; mini.Height = mh; double x = (164 - mw) / 2, y = (112 - mh) / 2; Canvas.SetLeft(mini, x); Canvas.SetTop(mini, y); double rw = Math.Min(1, ActualWidth / image.Width), rh = Math.Min(1, ActualHeight / image.Height); viewport.Width = Math.Max(2, mw * rw); viewport.Height = Math.Max(2, mh * rh); Canvas.SetLeft(viewport, x + mw * scroll.HorizontalOffset / image.Width); Canvas.SetTop(viewport, y + mh * scroll.VerticalOffset / image.Height); }
    void MapPan(MouseEventArgs e) { if (bitmap == null) return; var p = e.GetPosition(map); double scale = Math.Min(164.0 / bitmap.PixelWidth, 112.0 / bitmap.PixelHeight), mw = bitmap.PixelWidth * scale, mh = bitmap.PixelHeight * scale; scroll.ScrollToHorizontalOffset((p.X - (164 - mw) / 2) / mw * image.Width - ActualWidth / 2); scroll.ScrollToVerticalOffset((p.Y - (112 - mh) / 2) / mh * image.Height - ActualHeight / 2); }
}

